"""Auto-generated round-trip probe for headroom.transforms.lossless_compaction (2 pair(s)).

Detected from inverse function names; generated by `run.py autoprobe`."""

from __future__ import annotations

import headroom.transforms.lossless_compaction as _m

import json

# Inputs are chosen to make compressing/encoding pairs actually engage: long runs,
# repeated stanzas, arrays with repeated items, unicode, empty and padded text.
INPUTS = [
    "",
    "a",
    "x\n" * 60,
    ("line\n" * 40).strip(),
    ("a\nb\nc\n" * 12).strip(),
    "a\nb\na\nb\n" * 10,
    json.dumps({"a": 1, "b": [1, 2, 3], "c": {"d": "e"}}),
    json.dumps([{"id": i % 3, "v": "same"} for i in range(40)]),
    json.dumps({"rows": [{"id": i, "v": "x"} for i in range(40)]}),
    json.dumps([{"k": "中文 😀", "v": None}] * 30, ensure_ascii=False),
    "  padded  \n\nblank\n",
]

PAIRS = [('collapse_runs', 'expand_runs'), ('fold_repeated_blocks', 'unfold_repeated_blocks')]


def main() -> int:
    failures = []
    exercised = 0
    for forward_name, backward_name in PAIRS:
        forward = getattr(_m, forward_name, None)
        backward = getattr(_m, backward_name, None)
        if forward is None or backward is None:
            continue
        for value in INPUTS:
            try:
                middle = forward(value)
                if middle == value:
                    continue
                exercised += 1
                restored = backward(middle)
            except Exception:
                continue
            if restored != value:
                failures.append(
                    f"{forward_name}->{backward_name} did not restore the input: "
                    f"{value[:80]!r}"
                )
                break
    if failures:
        print("FAIL (" + str(len(failures)) + " pair(s))")
        for failure in failures:
            print(" -", failure)
        return 1
    if exercised == 0:
        print("INCONCLUSIVE: no pair changed any input")
        return 2
    print(f"PASS: {len(PAIRS)} pair(s), {exercised} round-trip(s) restored the input")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
